// Generated by Claude/specs/courses-tools/sync-ielts-exams.js from Claude/specs/lxd-course-ielts-exams/exam-05/ (farin-lxd). Do not hand-edit.
(function(E){ const x = E["exam-05"] = E["exam-05"] || {units:{}}; (x.units = x.units || {})["x05-l3"] = {"id":"x05-l3","patterns":["L3-science","PARA-opinion"],"title":{"en":"Listening Part 3: presenting a survey","tr":"Listening Part 3: bir anketi sunmak","fa":"Listening Part 3: ارائه‌ی یک نظرسنجی"},"objective":{"en":"In this lesson you will learn to follow two students discussing their own research: pick the two answers they finally agree on, tell a suggestion from a decision, and catch what each speaker really thinks.","tr":"Bu derste kendi araştırmalarını tartışan iki öğrenciyi takip etmeyi öğreneceksin: sonunda üzerinde anlaştıkları iki cevabı seçecek, öneriyi karardan ayıracak ve her konuşanın gerçekte ne düşündüğünü yakalayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را درباره‌ی پژوهش خودشان دنبال کنی: دو جوابی را که آخر سر رویش توافق می‌کنند انتخاب کنی، پیشنهاد را از تصمیم جدا کنی و بفهمی هر گوینده واقعاً چه فکری دارد."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 3: presenting a survey","tr":"Listening Part 3: bir anketi sunmak","fa":"Listening Part 3: ارائه‌ی یک نظرسنجی"},"objective":{"en":"In this lesson you will learn to follow two students discussing their own research: pick the two answers they finally agree on, tell a suggestion from a decision, and catch what each speaker really thinks.","tr":"Bu derste kendi araştırmalarını tartışan iki öğrenciyi takip etmeyi öğreneceksin: sonunda üzerinde anlaştıkları iki cevabı seçecek, öneriyi karardan ayıracak ve her konuşanın gerçekte ne düşündüğünü yakalayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را درباره‌ی پژوهش خودشان دنبال کنی: دو جوابی را که آخر سر رویش توافق می‌کنند انتخاب کنی، پیشنهاد را از تصمیم جدا کنی و بفهمی هر گوینده واقعاً چه فکری دارد."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Choose TWO","tr":"İKİ seç","fa":"دو تا انتخاب کن"},"value":"3 ×"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: sleep and screens","tr":"Bu sınav: uyku ve ekranlar","fa":"این آزمون: خواب و صفحه‌نمایش"},"intro":{"en":"Part 3 is always about study. Here two students who ran a survey on sleep plan their presentation. Science, health and the mind are among the most common Part 3 topics.","tr":"Part 3 her zaman ders çalışmayla ilgilidir. Burada uyku üzerine anket yapan iki öğrenci sunumlarını planlıyor. Bilim, sağlık ve zihin Part 3’ün en sık çıkan konuları arasındadır.","fa":"Part 3 همیشه درباره‌ی درس است. این‌جا دو دانشجو که درباره‌ی خواب نظرسنجی کرده‌اند ارائه‌شان را برنامه‌ریزی می‌کنند. علم، سلامت و ذهن از رایج‌ترین موضوع‌های Part 3 هستند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x05-l3-ctx","exam":true,"patterns":["L3-science","PARA-opinion"],"often":{"pattern":"L3-science","n":19,"of":40,"label":{"en":"Comes up often in the real exam: 19 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 19’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Two students present their survey","tr":"İki öğrenci anketlerini sunuyor","fa":"دو دانشجو نظرسنجی‌شان را ارائه می‌دهند"},"asks":{"en":"Two students go through the results of their own survey: what surprised them, what went wrong, what goes into the presentation, what they think of other research and what they will do next.","tr":"İki öğrenci kendi anketlerinin sonuçlarını gözden geçiriyor: onları neyin şaşırttığını, neyin ters gittiğini, sunuma neyin gireceğini, başka araştırmalar hakkında ne düşündüklerini ve sonra ne yapacaklarını.","fa":"دو دانشجو نتیجه‌های نظرسنجی خودشان را مرور می‌کنند: چه چیزی غافلگیرشان کرد، چه چیزی خراب شد، چه چیزی در ارائه می‌آید، درباره‌ی پژوهش‌های دیگر چه فکر می‌کنند و قدم بعدی‌شان چیست."},"fields":["Surprising findings","Problems with the survey","What to include","Views on other research","Next steps"],"words":[{"a":"surprised","b":"I had no idea / that was new to me / took me by surprise","tr":"şaşırmış","fa":"غافلگیر شده"},{"a":"not surprised","b":"we expected that / exactly as you’d expect","tr":"şaşırmamış","fa":"تعجب نکرده"},{"a":"responses","b":"answers / people who filled it in","tr":"yanıtlar","fa":"پاسخ‌ها"},{"a":"misunderstood","b":"people understood it in different ways","tr":"yanlış anlaşıldı","fa":"بد فهمیده شد"},{"a":"reject an idea","b":"it would take ages / we’d look silly","tr":"bir fikri reddetmek","fa":"رد کردن یک ایده"},{"a":"agree","b":"I’d go along with that / fair enough / good point","tr":"katılmak","fa":"موافق بودن"},{"a":"doubt","b":"I’m not convinced / I wouldn’t trust","tr":"şüphe","fa":"تردید"},{"a":"exaggerated","b":"blown out of proportion / more attention than it deserves","tr":"abartılmış","fa":"اغراق‌شده"},{"a":"irregular","b":"at a different time every day","tr":"düzensiz","fa":"نامنظم"},{"a":"routine","b":"doing things at the same time each day","tr":"rutin, düzen","fa":"برنامه‌ی ثابت روزانه"},{"a":"accurate","b":"you can trust the numbers","tr":"doğru, isabetli","fa":"دقیق"},{"a":"rehearse","b":"run through the whole thing / practise it","tr":"prova etmek","fa":"تمرین کردن، دوره کردن"}],"traps":[{"en":"Surprise questions: \"We expected that\" or \"that was in the article\" means it did not surprise them. Wait for \"I had no idea\" or \"what really surprised me\".","tr":"Şaşırma soruları: \"Bunu bekliyorduk\" ya da \"o makalede vardı\" onları şaşırtmadığı anlamına gelir. \"Hiç bilmiyordum\" ya da \"beni asıl şaşırtan\" ifadesini bekle.","fa":"سؤال‌های تعجب: «انتظارش را داشتیم» یا «آن در مقاله بود» یعنی غافلگیرشان نکرده. منتظر «اصلاً نمی‌دانستم» یا «چیزی که واقعاً غافلگیرم کرد» بمان."},{"en":"A suggestion is not a decision: one student suggests, the other rejects. Choose only what both accept.","tr":"Öneri karar değildir: bir öğrenci önerir, diğeri reddeder. Yalnızca ikisinin de kabul ettiğini seç.","fa":"پیشنهاد یعنی تصمیم نیست: یک دانشجو پیشنهاد می‌دهد و دیگری رد می‌کند. فقط چیزی را انتخاب کن که هر دو قبول دارند."},{"en":"An opinion question: the speaker may mention all three options and agree with only one. Listen for I’m not convinced, I’d go along with that, I wouldn’t trust.","tr":"Görüş sorusu: konuşan üç seçeneğin hepsinden söz edip yalnızca birine katılabilir. I’m not convinced, I’d go along with that, I wouldn’t trust ifadelerine kulak ver.","fa":"سؤال نظر: ممکن است گوینده از هر سه گزینه حرف بزند و فقط با یکی موافق باشد. به I’m not convinced، I’d go along with that و I wouldn’t trust گوش بده."}],"example":{"lines":[["Student A","Shall we include a map of the campus?"],["Student B","I’m not sure it adds much. But a table of the results, yes, definitely."],["Student A","Fair enough."]],"item":"What will they include? A a map  B a table","answer":"B","why":{"en":"The map is suggested and rejected (\"not sure it adds much\"); both accept the table.","tr":"Harita öneriliyor ve reddediliyor (\"pek bir şey katacağını sanmıyorum\"); ikisi de tabloyu kabul ediyor.","fa":"نقشه پیشنهاد و رد می‌شود («فکر نمی‌کنم چیز زیادی اضافه کند»)؛ هر دو جدول را قبول می‌کنند."}}},{"id":"L3-food","ctx":["L3-food","L3-science"],"title":{"en":"Food, health and the mind","tr":"Beslenme, sağlık ve zihin","fa":"غذا، سلامت و ذهن"},"asks":{"en":"Two students, sometimes with a tutor, plan or review a project on food, diet, sleep or how people think and feel. Questions ask what they decide, what they think of a source or a method, what went wrong and what they will do next.","tr":"İki öğrenci, bazen bir hocayla, yiyecek, beslenme, uyku ya da insanların nasıl düşünüp hissettiği üzerine bir projeyi planlar ya da değerlendirir. Sorular neye karar verdiklerini, bir kaynak ya da yöntem hakkında ne düşündüklerini, neyin ters gittiğini ve sırada ne yapacaklarını sorar.","fa":"دو دانشجو، گاهی با یک استاد، پروژه‌ای درباره‌ی غذا، رژیم غذایی، خواب یا اینکه آدم‌ها چطور فکر می‌کنند و چه حسی دارند را برنامه‌ریزی یا بررسی می‌کنند. سؤال‌ها می‌پرسند به چه تصمیمی می‌رسند، درباره‌ی یک منبع یا روش چه فکر می‌کنند، چه چیزی خراب شد و قدم بعدی‌شان چیست."},"fields":["What did the survey show about eating habits?","What is the students’ opinion of the article?","Which TWO factors are linked to poor sleep?","What does each study suggest?"],"words":[{"a":"diet","b":"what people eat","tr":"beslenme","fa":"رژیم غذایی"},{"a":"nutrition","b":"the goodness in food","tr":"besin değeri","fa":"تغذیه"},{"a":"ingredients","b":"what it's made from","tr":"içindekiler","fa":"مواد تشکیل‌دهنده"},{"a":"label","b":"the information on the packet","tr":"etiket","fa":"برچسب"},{"a":"obesity","b":"being seriously overweight","tr":"obezite","fa":"چاقی"},{"a":"consumers","b":"the people who buy it","tr":"tüketiciler","fa":"مصرف‌کننده‌ها"},{"a":"participants","b":"the people in the study","tr":"katılımcılar","fa":"شرکت‌کننده‌ها"},{"a":"linked to","b":"is connected with","tr":"... ile bağlantılı","fa":"مرتبط با"},{"a":"anxiety","b":"worry / feeling stressed","tr":"kaygı","fa":"اضطراب"},{"a":"lifestyle","b":"the way people live","tr":"yaşam tarzı","fa":"سبک زندگی"},{"a":"evidence","b":"data that shows it","tr":"kanıt","fa":"شواهد"},{"a":"misleading","b":"gives the wrong idea","tr":"yanıltıcı","fa":"گمراه‌کننده"},{"a":"sample size","b":"how many people were tested","tr":"örneklem büyüklüğü","fa":"حجم نمونه"}],"traps":[{"en":"The study’s claim and the students’ view are different: \"the article says sugar is the main cause, but I think that’s too simple\".","tr":"Çalışmanın iddiası ile öğrencilerin görüşü farklıdır: \"makale asıl nedenin şeker olduğunu söylüyor ama bence bu fazla basit\".","fa":"ادعای پژوهش با نظر دانشجوها فرق دارد: «مقاله می‌گوید علت اصلی شکر است، ولی به نظرم این خیلی ساده‌انگارانه است»."},{"en":"Survey numbers: \"most people\", \"a few people\" and \"nobody\" lead to different answers.","tr":"Anket sayıları: \"çoğu insan\", \"birkaç kişi\" ve \"hiç kimse\" farklı cevaplara götürür.","fa":"عددهای نظرسنجی: «بیشتر آدم‌ها»، «چند نفر» و «هیچ‌کس» به جواب‌های متفاوت می‌رسند."}],"example":{"lines":[["Student A","The article blames phones for poor sleep."],["Student B","Partly, but the study we read found that late coffee was a bigger factor."],["Student A","True. The data on caffeine was much stronger."]],"item":"What do the students agree is the main factor?  A mobile phones   B late caffeine   C noise","answer":"B","why":{"en":"Phones are only \"partly\" to blame. Both students accept that the caffeine data was stronger.","tr":"Telefonlar yalnızca \"kısmen\" suçlu. İki öğrenci de kafein verisinin daha güçlü olduğunu kabul ediyor.","fa":"گوشی فقط «تا حدی» مقصر است. هر دو دانشجو قبول می‌کنند که داده‌های کافئین قوی‌تر بود."}},"general":true,"patterns":["L3-science"],"often":{"pattern":"L3-science","n":19,"of":40,"label":{"en":"Comes up often in the real exam: 19 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 19’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۹ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three pairs, then four A-C questions","tr":"Üç çift, sonra dört A-C sorusu","fa":"سه جفت، بعد چهار سؤال A-C"},"body":{"en":"Questions 21-26 are three choose-TWO pairs, A-E. Questions 27-30 are A, B or C, usually about what one speaker thinks. You read Questions 21-26 first, then Questions 27-30 in the break.","tr":"Soru 21-26, A-E’den üç İKİ seç çiftidir. Soru 27-30 A, B ya da C’dir; genelde konuşanlardan birinin ne düşündüğüyle ilgilidir. Önce Soru 21-26’yı, aradaki molada Soru 27-30’u okursun.","fa":"سؤال‌های ۲۱ تا ۲۶ سه جفت «دو تا انتخاب کن» از A تا E هستند. سؤال‌های ۲۷ تا ۳۰ A، B یا C هستند و معمولاً درباره‌ی نظر یکی از گوینده‌ها. اول سؤال‌های ۲۱ تا ۲۶ را می‌خوانی، بعد در وقفه سؤال‌های ۲۷ تا ۳۰ را."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Yes, no or not yet","tr":"Evet, hayır ya da henüz değil","fa":"بله، نه یا هنوز نه"},"steps":[{"en":"Read the question word carefully: surprised, problems, include, think, next.","tr":"Soru kelimesini dikkatle oku: surprised, problems, include, think, next.","fa":"کلمه‌ی سؤال را دقیق بخوان: surprised، problems، include، think، next."},{"en":"As each option comes up, mark it yes, no or not yet. One speaker’s idea is \"not yet\" until the other answers.","tr":"Her seçenek geçtikçe evet, hayır ya da henüz değil diye işaretle. Bir konuşanın fikri, diğeri cevap verene kadar \"henüz değil\"dir.","fa":"هر گزینه که مطرح می‌شود، بله، نه یا هنوز نه علامت بزن. ایده‌ی یک نفر تا وقتی دیگری جواب نداده «هنوز نه» است."},{"en":"For A-C opinion questions, listen for the reason the speaker gives, not just the topic words.","tr":"A-C görüş sorularında yalnızca konu kelimelerini değil, konuşanın verdiği nedeni dinle.","fa":"در سؤال‌های نظر A-C، فقط به کلمه‌های موضوع گوش نده؛ به دلیلی که گوینده می‌آورد گوش بده."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"What was expected, read or rejected","tr":"Beklenen, okunan ya da reddedilen","fa":"آنچه انتظارش می‌رفت، خوانده شد یا رد شد"},"body":{"en":"Wrong options are usually things the students expected, things they read about in someone else’s work, or ideas one of them rejects. A rejected idea can sound attractive: \"It would look good, but...\" The word after but decides.","tr":"Yanlış seçenekler genelde öğrencilerin beklediği şeyler, başkasının çalışmasında okudukları şeyler ya da birinin reddettiği fikirlerdir. Reddedilen bir fikir cazip görünebilir: \"Güzel görünürdü ama...\" But’tan sonra gelen kelime karar verir.","fa":"گزینه‌های غلط معمولاً چیزهایی‌اند که دانشجوها انتظارش را داشتند، چیزهایی که در کار کس دیگری خوانده‌اند یا ایده‌هایی که یکی‌شان رد می‌کند. ایده‌ی ردشده ممکن است جذاب به نظر برسد: «قشنگ می‌شد، اما...». کلمه‌ی بعد از but تصمیم را مشخص می‌کند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"An opinion question, step by step","tr":"Bir görüş sorusu, adım adım","fa":"یک سؤال نظر، قدم به قدم"},"instruction":"Choose the correct letter, A, B or C.","item":"What does the woman think about the library survey? A It was too long.  B Its questions were unclear.  C It reached too few people.","lines":[["Man","Wasn’t that library survey far too long?"],["Woman","Twenty questions is fine, really. And a thousand people answered it. My problem is that half the questions could mean two different things."]],"answer":"B","walk":[{"en":"A: the man says \"too long\"; she answers \"twenty questions is fine\" = no.","tr":"A: adam \"çok uzun\" diyor; kadın \"yirmi soru gayet iyi\" diyor = hayır.","fa":"A: مرد می‌گوید «خیلی طولانی»؛ زن می‌گوید «بیست سؤال اشکالی ندارد» یعنی نه."},{"en":"C: \"a thousand people answered\" = it reached many people, so no.","tr":"C: \"bin kişi cevapladı\" = birçok kişiye ulaştı, yani hayır.","fa":"C: «هزار نفر جواب دادند» یعنی به آدم‌های زیادی رسید، پس نه."},{"en":"B: \"could mean two different things\" = unclear questions. This is her own view.","tr":"B: \"iki farklı anlama gelebilir\" = belirsiz sorular. Bu onun kendi görüşü.","fa":"B: «ممکن است دو معنی متفاوت داشته باشد» یعنی سؤال‌های نامشخص. این نظر خود اوست."}]},"quick":{"prompt":"\"A podcast? I’m not convinced. It would take a week to record, and we’ve got three days.\" What does the speaker think of the podcast idea?","options":["It would take too long to make.","It is a good idea.","It would be too expensive."],"correct":0,"why":{"en":"\"I’m not convinced\" rejects the idea, and the reason is time: a week to record, three days left.","tr":"\"I’m not convinced\" fikri reddediyor; nedeni zaman: kaydı bir hafta sürer, üç gün kaldı.","fa":"«I’m not convinced» ایده را رد می‌کند و دلیلش زمان است: ضبطش یک هفته طول می‌کشد و سه روز مانده."}},"remember":{"en":"Mark each option yes, no or not yet, and choose only what both students finally accept.","tr":"Her seçeneği evet, hayır ya da henüz değil diye işaretle ve yalnızca iki öğrencinin de sonunda kabul ettiğini seç.","fa":"هر گزینه را بله، نه یا هنوز نه علامت بزن و فقط چیزی را انتخاب کن که آخر سر هر دو دانشجو قبول می‌کنند."},"type":"explain","id":"c-x05-l3-e","course":"ielts-exams","exam":"exam-05","unit":"x05-l3"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 3","title":{"en":"Sleep and screens: a student survey","tr":"Uyku ve ekranlar: bir öğrenci anketi","fa":"خواب و صفحه‌نمایش: یک نظرسنجی دانشجویی"},"timed":7,"ctx":["L3-science"],"script":[{"who":"Joe","line":"So, Hannah, we've got all three hundred survey responses in now. Shall we go through what we found before we plan the presentation?"},{"who":"Hannah","line":"Yes, good idea. I suppose the first thing is that almost everyone looks at their phone in bed."},{"who":"Joe","line":"Well, we both expected that. I'd have been more surprised if they didn't. What really took me by surprise was the year groups. I'd assumed the first-years would sleep the least, with all the parties."},{"who":"Hannah","line":"Me too. But it's the final-year students who get the least sleep, by nearly an hour a night. I had no idea the gap was that big."},{"who":"Joe","line":"And the night-mode setting. Hardly anyone uses it, even though it's on every phone. That was new to me as well."},{"who":"Hannah","line":"Mm. What about reading in bed? Didn't someone say people with paper books slept longer?"},{"who":"Joe","line":"That was in the article we read. We never actually asked about books, so we can't say anything about that. And weekends were exactly as you'd expect: everyone sleeps longer."},{"who":"Hannah","line":"Right. Then we should be honest about the problems with the survey. Three hundred responses sounds like a lot, but nearly all of them came from arts and social sciences. We hardly heard from engineering or medicine."},{"who":"Joe","line":"True. And the screen-time question was a mistake. Some people counted watching television, some only counted their phones, and a few added their laptop for studying. So the numbers aren't really comparable."},{"who":"Hannah","line":"At least it was short. Five minutes, and nobody complained about the length."},{"who":"Joe","line":"And the online form worked perfectly, which was a relief after last term. Some people might not have been completely truthful, I suppose, but we've got no reason to think so."},{"who":"Hannah","line":"OK. So what goes into the presentation? I definitely want a graph comparing the year groups. It's our clearest result."},{"who":"Joe","line":"Agreed. What about a short video? We could film someone scrolling at two in the morning."},{"who":"Hannah","line":"It would look good, but it would take ages to make, and we've only got ten minutes to present. I'd rather spend the time on the findings."},{"who":"Joe","line":"Fair enough. A live poll of the audience, then? Everyone votes on their phones."},{"who":"Hannah","line":"Dr Patel said the wifi in that room is really unreliable. If it fails, we'd look silly."},{"who":"Joe","line":"Good point. What she did recommend was finishing with some practical advice for students, things they can actually change."},{"who":"Hannah","line":"Yes, let's do that. And no interview quotes, obviously, because we didn't do any interviews."},{"who":"Joe","line":"Now, the literature section. What did you make of the research on blue light? You read most of it."},{"who":"Hannah","line":"Honestly, I'm not convinced it deserves all the attention. The headlines make it sound as if the light from screens is the main problem, but when you read the actual studies, the effect on sleep is quite small. It's been blown out of proportion."},{"who":"Joe","line":"Interesting. In our data, I don't think the light is the issue at all. Noise in the halls is annoying, but most people say they've got earplugs. And worrying about deadlines matters, of course. But the thing that really stands out is that students go to bed at a different time every night. Midnight one day, three the next."},{"who":"Hannah","line":"I'd go along with that. Our best sleepers were the ones with a routine, even a late one."},{"who":"Joe","line":"What about that sleep app the tutor mentioned? Should we recommend it?"},{"who":"Hannah","line":"I tried it for a week. It's nicely designed and it's free, but it can't really measure the stages of sleep from a phone lying on the mattress. It told me I'd been in deep sleep when I was actually awake reading."},{"who":"Joe","line":"Same here. I wouldn't trust the numbers it gives. So we mention it, but with a warning."},{"who":"Hannah","line":"So, next steps. We could try to get more responses from engineering and medicine."},{"who":"Joe","line":"There isn't time for that before Friday. And Dr Patel's away until Monday, so we can't get her feedback either. I think we should run through the whole presentation with a timer on Thursday afternoon. Last time we went four minutes over."},{"who":"Hannah","line":"Don't remind me. OK, Thursday at two, in the library. I'll book a room."}],"groups":[{"instruction":"Questions 21-22. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":21,"n2":22,"kind":"mcq2","prompt":"Which TWO findings from the survey surprised the students?","options":["A Most students use their phones in bed.","B Final-year students sleep less than first-years.","C Students who read paper books sleep longer.","D Few students use the night-mode setting.","E Students sleep longer at weekends."],"correct":[1,3],"evidence":"it's the final-year students who get the least sleep","why":{"en":"Phones in bed and longer weekend sleep were expected, and books were never asked about. The year groups (B) \"took me by surprise\", and night mode (D) \"was new to me\".","tr":"Yatakta telefon ve hafta sonu daha uzun uyku bekleniyordu, kitaplar ise hiç sorulmadı. Sınıf grupları (B) \"beni şaşırttı\", gece modu (D) da \"benim için yeniydi\".","fa":"گوشی در رختخواب و خواب بیشتر در آخر هفته قابل انتظار بود و درباره‌ی کتاب هم اصلاً نپرسیده بودند. گروه‌های سنی (B) «غافلگیرم کرد» و حالت شب (D) «برایم تازه بود»."},"trap":["TR-ruledout","TR-paraphrase"]}]},{"instruction":"Questions 23-24. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":23,"n2":24,"kind":"mcq2","prompt":"Which TWO problems with their survey do the students mention?","options":["A Some departments sent very few responses.","B One question was understood in different ways.","C The survey took too long to complete.","D Some students gave false answers.","E The online form stopped working."],"correct":[0,1],"evidence":"We hardly heard from engineering or medicine","why":{"en":"It was short, the form \"worked perfectly\", and there is \"no reason to think\" answers were false. Few responses from engineering and medicine (A) and the screen-time question (B) were real problems.","tr":"Anket kısaydı, form \"kusursuz çalıştı\" ve cevapların yanlış olduğunu \"düşünmek için bir neden yok\". Mühendislik ve tıptan az yanıt (A) ve ekran süresi sorusu (B) gerçek sorunlardı.","fa":"نظرسنجی کوتاه بود، فرم «بی‌نقص کار کرد» و «دلیلی ندارد فکر کنیم» جواب‌ها دروغ بودند. پاسخ کم از مهندسی و پزشکی (A) و سؤال زمان صفحه‌نمایش (B) مشکل‌های واقعی بودند."},"trap":["TR-ruledout","TR-paraphrase"]}]},{"instruction":"Questions 25-26. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":25,"n2":26,"kind":"mcq2","prompt":"Which TWO things will the students include in their presentation?","options":["A a graph comparing year groups","B quotes from interviews","C a live poll of the audience","D useful tips for learners","E a short video"],"correct":[0,3],"evidence":"finishing with some practical advice for students","why":{"en":"The video \"would take ages\", the poll depends on unreliable wifi, and there were no interviews. Both accept the graph (A) and practical advice (D).","tr":"Video \"çok uzun sürerdi\", anket güvenilmez wifi’ye bağlı ve hiç röportaj yapılmadı. İkisi de grafiği (A) ve pratik tavsiyeleri (D) kabul ediyor.","fa":"ویدیو «خیلی طول می‌کشد»، رأی‌گیری به وای‌فای ناپایدار بستگی دارد و مصاحبه‌ای هم نبوده. هر دو نمودار (A) و توصیه‌های عملی (D) را قبول می‌کنند."},"trap":["TR-ruledout"]}]},{"instruction":"Questions 27-30. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":27,"kind":"mcq","prompt":"What does Hannah think about the research on blue light from screens?","options":["A Its importance has been exaggerated.","B It is too technical for their presentation.","C It explains most of their results."],"correct":0,"evidence":"It's been blown out of proportion","why":{"en":"\"I’m not convinced it deserves all the attention... blown out of proportion\" = exaggerated.","tr":"\"Bu kadar ilgiyi hak ettiğine ikna olmadım... abartıldı\" = önemi abartılmış.","fa":"«قانع نشده‌ام که این‌همه توجه لازم دارد... بیش از حد بزرگش کرده‌اند» یعنی اغراق شده."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":28,"kind":"mcq","prompt":"According to Joe, what is the main cause of poor sleep in their data?","options":["A noise in student halls","B worry about deadlines","C going to bed at irregular times"],"correct":2,"evidence":"students go to bed at a different time every night","why":{"en":"Noise is solved by earplugs and deadlines \"matter, of course\", but \"the thing that really stands out\" is a different bedtime every night.","tr":"Gürültüyü kulak tıkaçları çözüyor, teslim tarihleri de \"elbette önemli\", ama \"asıl göze çarpan\" her gece farklı bir yatma saati.","fa":"سروصدا با گوش‌گیر حل می‌شود و ضرب‌الاجل‌ها «البته مهم‌اند»، اما «چیزی که واقعاً به چشم می‌آید» ساعت خواب متفاوت هر شب است."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":29,"kind":"mcq","prompt":"What do the students agree about the sleep app?","options":["A It is too expensive.","B Its measurements are not reliable.","C It is badly designed."],"correct":1,"evidence":"I wouldn't trust the numbers it gives","why":{"en":"It is free and \"nicely designed\". Both say it cannot measure sleep properly: \"I wouldn’t trust the numbers\".","tr":"Ücretsiz ve \"güzel tasarlanmış\". İkisi de uykuyu düzgün ölçemediğini söylüyor: \"verdiği rakamlara güvenmem\".","fa":"رایگان است و «طراحی قشنگی دارد». هر دو می‌گویند خواب را درست اندازه نمی‌گیرد: «به عددهایش اعتماد نمی‌کنم»."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":30,"kind":"mcq","prompt":"What will the students do next?","options":["A ask their tutor for feedback","B practise the presentation","C collect more survey responses"],"correct":1,"evidence":"run through the whole presentation with a timer on Thursday afternoon","why":{"en":"More responses would take too long and the tutor is away. They will \"run through the whole presentation with a timer\" = practise.","tr":"Daha fazla yanıt çok uzun sürer, hoca da yok. Sunumu \"baştan sona süre tutarak prova edecekler\".","fa":"پاسخ بیشتر خیلی طول می‌کشد و استاد هم نیست. ارائه را «از اول تا آخر با زمان‌سنج تمرین می‌کنند»."},"trap":["TR-ruledout","TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Hannah":{"accent":"Australian","gender":"F","tts":{"engine":"kokoro","voice":"af_nicole","fallback":true,"note":"Australian wanted; no free Australian voice yet"},"role":"Student"},"Joe":{"accent":"British (Southern English)","gender":"M","tts":{"engine":"kokoro","voice":"bm_fable"},"role":"Student"}},"sequence":[{"type":"announcer","text":"Part 3. You will hear two students, Hannah and Joe, discussing their survey on sleep and screen use and planning a presentation. First, you have some time to look at Questions 21 to 26."},{"type":"pause","seconds":30,"note":"reading time, Questions 21-26"},{"type":"announcer","text":"Now listen carefully and answer Questions 21 to 26."},{"type":"sfx","note":"quiet study room, low background"},{"type":"lines","from":0,"to":17},{"type":"announcer","text":"Before you hear the rest of the discussion, you have some time to look at Questions 27 to 30."},{"type":"pause","seconds":30,"note":"reading time, Questions 27-30"},{"type":"announcer","text":"Now listen and answer Questions 27 to 30."},{"type":"lines","from":18,"to":27},{"type":"announcer","text":"That is the end of Part 3. You now have half a minute to check your answers.","after":30}]},"id":"c-x05-l3-d","course":"ielts-exams","exam":"exam-05","unit":"x05-l3"},"exit":{"type":"exit","items":[{"tests":"paraphrase","point":1,"prompt":"In a recording, \"that was exactly as you’d expect\" usually means the speakers were...","options":["very surprised","disappointed","not surprised"],"correct":2,"why":{"en":"Something you expected does not surprise you.","tr":"Beklediğin bir şey seni şaşırtmaz.","fa":"چیزی که انتظارش را داری غافلگیرت نمی‌کند."}},{"tests":"word","point":3,"prompt":"\"The problem has been blown out of proportion.\" This means the problem...","options":["has been solved","has been made to seem bigger than it is","has become much worse"],"correct":1,"why":{"en":"Blown out of proportion = exaggerated.","tr":"Blown out of proportion = abartılmış.","fa":"blown out of proportion یعنی اغراق‌شده."}},{"tests":"method","point":2,"prompt":"One student suggests an idea. The other says \"Good point, but we’d never finish it in time.\" How do you mark the idea?","options":["No: it was rejected","Yes: it was called a good point","Not yet: wait for the tutor"],"correct":0,"why":{"en":"\"But we’d never finish it\" turns the idea down, even after \"good point\".","tr":"\"Ama asla zamanında bitiremeyiz\" fikri reddediyor, \"good point\" denmiş olsa bile.","fa":"«اما هیچ‌وقت به‌موقع تمامش نمی‌کنیم» ایده را رد می‌کند، حتی بعد از «good point»."}},{"tests":"trap","point":3,"prompt":"\"That finding was in the article we read, but our survey didn’t ask about it.\" Did the students find it themselves?","options":["Yes","Only partly","No"],"correct":2,"why":{"en":"It came from someone else’s article, not from their own data.","tr":"Başka birinin makalesinden geliyor, kendi verilerinden değil.","fa":"از مقاله‌ی کس دیگری آمده، نه از داده‌های خودشان."}},{"tests":"method","point":1,"prompt":"Questions 21-22 say \"Choose TWO letters, A-E.\" You are sure of one letter only. What do you write?","options":["only the letter you are sure of","the letter you are sure of and your best guess","three letters, to be safe"],"correct":1,"why":{"en":"A blank gap gets nothing, and three letters break the instruction. Always write exactly two.","tr":"Boş bırakılan yer hiçbir şey kazandırmaz, üç harf de talimata aykırıdır. Her zaman tam olarak iki harf yaz.","fa":"جای خالی هیچ چیزی به تو نمی‌دهد و سه حرف هم خلاف دستورالعمل است. همیشه دقیقاً دو حرف بنویس."}}],"id":"c-x05-l3-x","course":"ielts-exams","exam":"exam-05","unit":"x05-l3"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
